import "server-only";
import { z } from "zod";
import { ApiError, apiFetch } from "@/lib/api";

const ProductSummarySchema = z.object({
  slug: z.string(),
  name: z.string(),
  category: z.enum(["packs", "tents", "apparel", "cooking"]),
  priceCents: z.number().int(),
  imageUrl: z.string(),
  rating: z.object({ average: z.number(), count: z.number().int() }),
  inStock: z.boolean(),
});

const ProductSchema = ProductSummarySchema.extend({
  description: z.string(),
  stock: z.number().int(),
  updatedAt: z.iso.datetime(),
});

const ReviewSchema = z.object({
  id: z.string(),
  rating: z.number().int().min(1).max(5),
  title: z.string(),
  body: z.string(),
  author: z.object({ name: z.string() }),
});

export type Product = z.infer<typeof ProductSchema>;
export type Review = z.infer<typeof ReviewSchema>;

export async function listProducts(category?: string) {
  const query = category ? `?category=${encodeURIComponent(category)}` : "";
  const page = await apiFetch(`/products${query}`);
  return z.object({ items: z.array(ProductSummarySchema) }).parse(page).items;
}

export async function getProduct(slug: string): Promise<Product | null> {
  try {
    return ProductSchema.parse(await apiFetch(`/products/${slug}`));
  } catch (error) {
    if (error instanceof ApiError && error.status === 404) return null;
    throw error;
  }
}

export async function getReviews(slug: string) {
  try {
    const page = await apiFetch(`/products/${slug}/reviews`);
    return z.object({ items: z.array(ReviewSchema) }).parse(page).items;
  } catch (error) {
    if (error instanceof ApiError && error.status === 404) return [];
    throw error;
  }
}

import { notFound } from "next/navigation";
import { formatPrice } from "@/lib/format";
import { getProduct, getReviews } from "@/lib/products";

export default async function ProductPage({ params }: PageProps<"/products/[slug]">) {
  const { slug } = await params;
  const product = await getProduct(slug);
  if (!product) notFound();
  const reviews = await getReviews(slug);

  return (
    <article>
      <h1 className="text-2xl font-semibold">{product.name}</h1>
      <p>{formatPrice(product.priceCents)}</p>
      <h2 className="font-semibold">Reviews</h2>
      <ul>
        {reviews.map((review) => (
          <li key={review.id}>{review.title}</li>
        ))}
      </ul>
    </article>
  );
}

import { notFound } from "next/navigation";
import { Suspense } from "react";
import { QuantityPicker } from "@/components/quantity-picker";
import { formatPrice } from "@/lib/format";
import { getProduct, getReviews } from "@/lib/products";

export default async function ProductPage({ params }: PageProps<"/products/[slug]">) {
  const { slug } = await params;
  const reviews = getReviews(slug);
  const product = await getProduct(slug);
  if (!product) notFound();

  return (
    <article className="grid gap-2">
      <h1 className="text-2xl font-semibold">{product.name}</h1>
      <p>{formatPrice(product.priceCents)}</p>
      {product.inStock ? <QuantityPicker max={Math.min(product.stock, 10)} /> : <p>Out of stock</p>}
      <h2 className="font-semibold">Reviews</h2>
      <Suspense fallback={<ReviewsSkeleton />}>
        <Reviews reviews={reviews} />
      </Suspense>
    </article>
  );
}

async function Reviews({ reviews }: { reviews: ReturnType<typeof getReviews> }) {
  const items = await reviews;
  if (items.length === 0) return <p>No reviews yet.</p>;
  return (
    <ul className="grid gap-2">
      {items.map((review) => (
        <li key={review.id} className="h-12">
          {review.rating}/5 {review.title}, by {review.author.name}
        </li>
      ))}
    </ul>
  );
}

function ReviewsSkeleton() {
  return (
    <ul className="grid gap-2" aria-label="Loading reviews">
      <li className="h-12 animate-pulse rounded bg-zinc-200" />
      <li className="h-12 animate-pulse rounded bg-zinc-200" />
    </ul>
  );
}

const url = process.argv[2];
const start = Date.now();
const res = await fetch(url);
const decoder = new TextDecoder();

for await (const chunk of res.body) {
  const text = decoder.decode(chunk, { stream: true });
  const seen = ["Loading product…", "Ember Stove", "Loading reviews", "Boils fast"].filter((s) => text.includes(s));
  const ms = String(Date.now() - start).padStart(5);
  const bytes = String(chunk.length).padStart(6);
  console.log(`${ms} ms ${bytes} bytes  ${seen.join(", ")}`);
}

steps.body:
Two components on one page often need the same data. The product page's title, set by `generateMetadata`, needs the product's name, and so does the page itself. You could fetch it once and pass it around, but metadata and the page are separate functions that Next.js calls on its own. What you want is for the second call to reuse the first one's answer.

## fetch is deduplicated for you

During one render, Next.js remembers every `fetch` with the `GET` method, keyed by its URL and options. A second `fetch` of the same URL during the same render gets the first one's response instead of going out again. This is called **memoization**, and it lasts only for one request's render: the next visitor's render starts empty. So two components that each call `getProduct("ember-stove")` send one request to the API.

## React's cache for everything else

Memoization covers `fetch` and nothing else. A database query, a call through another client library, or the zod parsing in `getProduct` all run again on every call. React's `cache` function covers those: wrap a function in it, and during one render, calls with the same arguments run the function once and share the result. It's the same per-render rule as fetch memoization, for any function.

```tsx sketch
import { cache } from "react";

export const getProduct = cache(async (slug: string): Promise<Product | null> => {
  // ...the same body as before
});
```

Arguments are compared by value for strings and numbers, and by identity for objects, so pass plain values. And `cache` only works on the server, during rendering. In the browser, or outside a render, it does nothing.

Don't confuse it with caching between requests. `cache` forgets everything as soon as the page is rendered, so the next visitor's page asks the API again. Keeping results across requests is what the `use cache` directive is for, in the next lesson.

## The preload pattern

`cache` also lets you start a request early from anywhere, without passing a promise around. Call the cached function without awaiting it, near the top of the page, and later calls with the same arguments get the request that's already running:

```tsx sketch
export function preloadProduct(slug: string) {
  void getProduct(slug);
}
```

`void` says you're starting the call on purpose and ignoring the result for now. A layout can call `preloadProduct(slug)` before it renders its children, and the component deep in the tree that awaits `getProduct(slug)` gets the request that's already halfway done. Starting early in the parent and passing the promise down, from the part on parallel requests, does the same job, and it's often clearer. Use preload when the component that needs the data is far from the place that knows it'll be needed.

